// Import required modules (libraries) that we need
var express = require('express');     // Web server framework
var fs = require('fs');              // File system operations (reading/writing files)
var path = require('path');          // Working with file paths
var cors = require('cors');          // Cross-Origin Resource Sharing
var axios = require('axios');        // HTTP client for making requests (we'll use this for external APIs if needed)

// Create an Express application instance
var app = express();

// Set the port number where our server will run
var PORT = 3000;

// Name of the file where we'll store our todos
var TODOS_FILE = 'todos.txt';

// Middleware setup (these run on every request)
app.use(cors());                          // Allow cross-origin requests
app.use(express.json());                  // Parse JSON data from request bodies
app.use(express.static('public'));        // Serve static files (HTML, CSS, JS) from 'public' folder

// Helper function to read todos from the text file
function readTodos(callback) {
    // Try to read the todos file
    fs.readFile(TODOS_FILE, 'utf8', function(error, data) {
        if (error) {
            // If file doesn't exist (ENOENT error), return empty array
            if (error.code === 'ENOENT') {
                callback(null, []); // null means no error, [] means empty todos
                return;
            }
            // If other error occurred, pass it to callback
            callback(error, null);
            return;
        }
        
        // File exists and was read successfully
        try {
            // If file has content, parse it as JSON, otherwise use empty array
            var todos = data.trim() ? JSON.parse(data) : [];
            callback(null, todos); // Success: no error, return todos
        } catch (parseError) {
            // If JSON parsing fails, return error
            callback(parseError, null);
        }
    });

// NEW ROUTES: Using axios to interact with external APIs

// GET /api/joke - Get a random joke from external API
app.get('/api/joke', function(req, res) {
    console.log('GET request received for /api/joke');
    
    // Use our axios function to get joke from external API
    getJokeFromAPI(function(error, joke) {
        if (error) {
            console.log('Failed to get joke:', error.message);
            res.status(500).json({ error: 'Failed to get joke from external API' });
            return;
        }
        
        // Send joke back to client
        res.json({ joke: joke, source: 'External Joke API' });
    });
});

// GET /api/user/:id - Get user info from external API
app.get('/api/user/:id', function(req, res) {
    var userId = req.params.id;
    console.log('GET request received for user ID:', userId);
    
    // Validate user ID is a number
    if (isNaN(userId) || userId < 1 || userId > 10) {
        res.status(400).json({ error: 'User ID must be a number between 1 and 10' });
        return;
    }
    
    // Use axios to get user info from external API
    getUserInfo(userId, function(error, userInfo) {
        if (error) {
            console.log('Failed to get user info:', error.message);
            res.status(500).json({ error: 'Failed to get user info from external API' });
            return;
        }
        
        // Send user info back to client
        res.json({
            user: {
                id: userInfo.id,
                name: userInfo.name,
                email: userInfo.email,
                city: userInfo.address.city
            },
            source: 'External User API'
        });
    });
});

