    };
    
    // Use axios to create post on external API
    createPostExample(postData, function(error, createdPost) {
        if (error) {
            console.log('Failed to create post:', error.message);
            res.status(500).json({ error: 'Failed to create post on external API' });
            return;
        }
        
        // Send created post info back to client
