// Helper function to write todos to the text file
function writeTodos(todos, callback) {
    // Convert todos array to formatted JSON string
    var todosJson = JSON.stringify(todos, null, 2); // null, 2 makes it pretty-printed
    
    // Write the JSON string to file
    fs.writeFile(TODOS_FILE, todosJson, function(error) {
        if (error) {
            callback(error); // Pass error to callback
        } else {
            callback(null);  // Success: no error
        }
    });
}

// API Routes (these handle different HTTP requests)

// GET /api/todos - Get all todos from file
app.get('/api/todos', function(req, res) {
    console.log('GET request received for /api/todos');
    
    // Call our helper function to read todos from file
    readTodos(function(error, todos) {
        if (error) {
            console.log('Error reading todos:', error);
            // Send error response to client
            res.status(500).json({ error: 'Failed to read todos' });
            return;
        }
        
        console.log('Successfully read', todos.length, 'todos');
        // Send todos back to client as JSON
        res.json(todos);
    });
});

// POST /api/todos - Add a new todo
app.post('/api/todos', function(req, res) {
    console.log('POST request received for /api/todos');
    console.log('Request body:', req.body);
    
    // Get the text from request body
    var text = req.body.text;
    
    // Validate that text exists and is not empty
    if (!text || text.trim() === '') {
        console.log('Invalid todo text provided');
        res.status(400).json({ error: 'Todo text is required' });
        return;
    }
    
    // First, read existing todos
    readTodos(function(readError, todos) {
        if (readError) {
            console.log('Error reading todos:', readError);
            res.status(500).json({ error: 'Failed to read existing todos' });
            return;
        }
        
        // Create new todo object
        var newTodo = {
            id: Date.now(),                    // Use timestamp as unique ID
            text: text.trim(),                 // Remove extra spaces
            completed: false,                  // New todos are not completed
            createdAt: new Date().toISOString() // Store creation time
        };
        
        console.log('Created new todo:', newTodo);
        
        // Add new todo to existing todos array
        todos.push(newTodo);
        
        // Write updated todos back to file
        writeTodos(todos, function(writeError) {
            if (writeError) {
                console.log('Error writing todos:', writeError);
                res.status(500).json({ error: 'Failed to save todo' });
                return;
            }
            
            console.log('Successfully saved new todo');
            // Send the new todo back to client with 201 status (Created)
            res.status(201).json(newTodo);
        });
    });
});

// PUT /api/todos/:id - Update a todo (toggle completion status)
app.put('/api/todos/:id', function(req, res) {
    // Get the ID from URL parameters and convert to number
    var id = parseInt(req.params.id);
    console.log('PUT request received for todo ID:', id);
    
    // Read current todos
    readTodos(function(readError, todos) {
        if (readError) {
            console.log('Error reading todos:', readError);
            res.status(500).json({ error: 'Failed to read todos' });
            return;
        }
        
        // Find the todo with matching ID
        var todoIndex = -1;
        for (var i = 0; i < todos.length; i++) {
            if (todos[i].id === id) {
                todoIndex = i;
                break;
            }
        }
        
        // Check if todo was found
        if (todoIndex === -1) {
            console.log('Todo not found with ID:', id);
            res.status(404).json({ error: 'Todo not found' });
            return;
        }
        
        // Toggle the completion status
        todos[todoIndex].completed = !todos[todoIndex].completed;
        console.log('Toggled todo completion. New status:', todos[todoIndex].completed);
        
        // Save updated todos to file
        writeTodos(todos, function(writeError) {
            if (writeError) {
                console.log('Error writing todos:', writeError);
                res.status(500).json({ error: 'Failed to update todo' });
                return;
            }
            
            console.log('Successfully updated todo');
            // Send updated todo back to client
            res.json(todos[todoIndex]);
        });
    });
});

