app.delete('/api/todos/:id', function(req, res) {
    // Get the ID from URL parameters and convert to number
    var id = parseInt(req.params.id);
    console.log('DELETE request received for todo ID:', id);
    
    // Read current todos
    readTodos(function(readError, todos) {
        if (readError) {
            console.log('Error reading todos:', readError);
            res.status(500).json({ error: 'Failed to read todos' });
            return;
        }
        
        // Filter out the todo with matching ID (keep all others)
        var filteredTodos = [];
        var found = false;
        
        for (var i = 0; i < todos.length; i++) {
            if (todos[i].id === id) {
                found = true; // Mark that we found the todo to delete
                // Don't add this todo to filteredTodos (effectively deleting it)
            } else {
                filteredTodos.push(todos[i]); // Keep this todo
            }
        }
        
        // Check if todo was found
        if (!found) {
            console.log('Todo not found with ID:', id);
            res.status(404).json({ error: 'Todo not found' });
            return;
        }
        
        // Save the filtered todos (without the deleted one) to file
        writeTodos(filteredTodos, function(writeError) {
            if (writeError) {
                console.log('Error writing todos:', writeError);
                res.status(500).json({ error: 'Failed to delete todo' });
                return;
            }
            
            console.log('Successfully deleted todo with ID:', id);
            // Send success message back to client
            res.json({ message: 'Todo deleted successfully' });
        });
    });
});

